    28     GLZ_ALWAYS_INLINE bool csv_new_line(is_context auto& ctx, auto&& it, auto&& end) noexcept
    29     {
    30        if (it == end) [[unlikely]] {
    31           ctx.error = error_code::unexpected_end;
    32           return true;
    33        }
    34
    35        if (*it == '\n') {
    36           ++it;
    37        }
    38        else if (*it == '\r') {
    39           ++it;
    40           if (it == end) [[unlikely]] {
    41              ctx.error = error_code::unexpected_end;
    42              return true;
    43           }
    44           if (*it == '\n') [[likely]] {
    45              ++it;
    46           }
    47           else [[unlikely]] {
    48              ctx.error = error_code::syntax_error;
    49              return true;
    50           }
    51        }
    52        else [[unlikely]] {
    53           ctx.error = error_code::syntax_error;
    54           return true;
    55        }
    56        return false;
    57     }
