    71     template <num_t T>
    72     struct from<CSV, T>
    73     {
    74        template <auto Opts, class It>
    75        static void op(auto&& value, is_context auto&& ctx, It&& it, auto&& end) noexcept
    76        {
    77           if (bool(ctx.error)) [[unlikely]] {
    78              return;
    79           }
    80
    81           if (it == end) [[unlikely]] {
    82              ctx.error = error_code::unexpected_end;
    83              return;
    84           }
    85
    86           using V = decay_keep_volatile_t<decltype(value)>;
    87           if constexpr (int_t<V>) {
    88              if constexpr (std::is_unsigned_v<V>) {
    89                 uint64_t i{};
    90                 if (*it == '-') [[unlikely]] {
    91                    ctx.error = error_code::parse_number_failure;
    92                    return;
    93                 }
    94
    95                 if (not glz::atoi(i, it, end)) [[unlikely]] {
    96                    ctx.error = error_code::parse_number_failure;
    97                    return;
    98                 }
    99
   100                 if (i > (std::numeric_limits<V>::max)()) [[unlikely]] {
   101                    ctx.error = error_code::parse_number_failure;
   102                    return;
   103                 }
   104                 value = static_cast<V>(i);
   105              }
   106              else {
   107                 uint64_t i{};
   108                 int sign = 1;
   109                 if (*it == '-') {
   110                    sign = -1;
   111                    ++it;
   112                    if (it == end) [[unlikely]] {
   113                       ctx.error = error_code::unexpected_end;
   114                       return;
   115                    }
   116                 }
   117                 if (not glz::atoi(i, it, end)) [[unlikely]] {
   118                    ctx.error = error_code::parse_number_failure;
   119                    return;
   120                 }
   121
   122                 if (i > (std::numeric_limits<V>::max)()) [[unlikely]] {
   123                    ctx.error = error_code::parse_number_failure;
   124                    return;
   125                 }
   126                 value = sign * static_cast<V>(i);
   127              }
   128           }
   129           else {
   130              auto [ptr, ec] = glz::from_chars<false>(it, end, value); // Always treat as non-null-terminated
   131              if (ec != std::errc()) [[unlikely]] {
   132                 ctx.error = error_code::parse_number_failure;
   133                 return;
   134              }
   135              it = ptr;
   136           }
   137        }
   138     };
