   140     // CSV spec: https://www.ietf.org/rfc/rfc4180.txt
   240           uint64_t temp;
   241           if (not glz::atoi(temp, it, end)) [[unlikely]] {
   242              ctx.error = error_code::expected_true_or_false;
   243              return;
   244           }
   245           value = static_cast<bool>(temp);
   246        }
