   267     inline auto read_column_wise_keys(auto&& ctx, auto&& it, auto&& end)
   268     {
   269        std::vector<std::pair<sv, size_t>> keys;
   270
   271        auto read_key = [&](auto&& start, auto&& it) {
   272           sv key{start, size_t(it - start)};
   273
   274           size_t csv_index{};
   275
   276           const auto brace_pos = key.find('[');
   277           if (brace_pos != sv::npos) {
   278              const auto close_brace = key.find(']');
   279              const auto index = key.substr(brace_pos + 1, close_brace - (brace_pos + 1));
   280              key = key.substr(0, brace_pos);
   281              const auto [ptr, ec] = std::from_chars(index.data(), index.data() + index.size(), csv_index);
   282              if (ec != std::errc()) {
   283                 ctx.error = error_code::syntax_error;
   284                 return;
   285              }
   286           }
   287
   288           keys.emplace_back(std::pair{key, csv_index});
   289        };
   290
   291        auto start = it;
   292        while (it != end) {
   293           if (*it == ',') {
   294              read_key(start, it);
   295              ++it;
   296              start = it;
   297           }
   298           else if (*it == '\r' || *it == '\n') {
   299              auto line_end = it; // Position before incrementing
   300              if (*it == '\r') {
   301                 ++it;
   302                 if (it != end && *it != '\n') [[unlikely]] {
   303                    ctx.error = error_code::syntax_error;
   304                    return keys;
   305                 }
   306              }
   307
   308              if (start == line_end) {
   309                 // trailing comma or empty
   310              }
   311              else {
   312                 read_key(start, line_end); // Use original line ending position
   313              }
   314              break;
   315           }
   316           else {
   317              ++it;
   318           }
   319        }
   320
   321        return keys;
   322     }
