   342                    key = key.substr(0, brace_pos);
   343                    const auto [ptr, ec] = std::from_chars(index.data(), index.data() + index.size(), csv_index);
   344                    if (ec != std::errc()) {
   345                       ctx.error = error_code::syntax_error;
   346                       return;
   347                    }
   348                 }
   349
   350                 if (it == end || *it != ',') [[unlikely]] {
   351                    ctx.error = error_code::syntax_error;
   352                    return;
   353                 }
   354                 ++it;
   355
   356                 using key_type = typename std::decay_t<decltype(value)>::key_type;
   357                 auto& member = value[key_type(key)];
   358                 using M = std::decay_t<decltype(member)>;
   359                 if constexpr (fixed_array_value_t<M> && emplace_backable<M>) {
   360                    size_t col = 0;
   361                    while (it != end) {
   362                       if (col < member.size()) [[likely]] {
