   364                       }
   365                       else [[unlikely]] {
   366                          parse<CSV>::op<Opts>(member.emplace_back()[csv_index], ctx, it, end);
   367                       }
   368
   369                       if (it == end) break;
   370
   371                       if (*it == '\r') {
   372                          ++it;
   373                          if (it != end && *it == '\n') {
   374                             ++it;
   375                          }
   376                          break;
   377                       }
   378                       else if (*it == '\n') {
   379                          ++it;
   380                          break;
   381                       }
   382
   383                       if (*it == ',') {
   384                          ++it;
   385                       }
   386                       else {
   387                          ctx.error = error_code::syntax_error;
   388                          return;
   389                       }
